function isPlain(value) {
  if (value === null || typeof value !== 'object') return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function setOwn(target, key, value) {
  Object.defineProperty(target, key, {
    value,
    enumerable: true,
    configurable: true,
    writable: true,
  });
}

function cloneValue(value, seen = new WeakMap()) {
  if (value === null || typeof value !== 'object') return value;
  if (seen.has(value)) return seen.get(value);

  if (Array.isArray(value)) {
    const copy = new Array(value.length);
    seen.set(value, copy);
    for (const key of Object.keys(value)) {
      setOwn(copy, key, cloneValue(value[key], seen));
    }
    return copy;
  }

  if (value instanceof Date) {
    const copy = new Date(value.getTime());
    seen.set(value, copy);
    return copy;
  }

  if (value instanceof RegExp) {
    const copy = new RegExp(value.source, value.flags);
    copy.lastIndex = value.lastIndex;
    seen.set(value, copy);
    return copy;
  }

  if (value instanceof Map) {
    const copy = new Map();
    seen.set(value, copy);
    for (const [key, entry] of value) {
      copy.set(cloneValue(key, seen), cloneValue(entry, seen));
    }
    return copy;
  }

  if (value instanceof Set) {
    const copy = new Set();
    seen.set(value, copy);
    for (const entry of value) copy.add(cloneValue(entry, seen));
    return copy;
  }

  if (ArrayBuffer.isView(value)) {
    const copy = value instanceof DataView
      ? new DataView(cloneValue(value.buffer, seen), value.byteOffset, value.byteLength)
      : new value.constructor(value);
    seen.set(value, copy);
    return copy;
  }

  if (value instanceof ArrayBuffer) {
    const copy = value.slice(0);
    seen.set(value, copy);
    return copy;
  }

  const copy = Object.create(Object.getPrototypeOf(value));
  seen.set(value, copy);
  for (const key of Object.keys(value)) {
    setOwn(copy, key, cloneValue(value[key], seen));
  }
  return copy;
}

function mergePlain(base, overlay) {
  const result = cloneValue(base);
  for (const [key, value] of Object.entries(overlay)) {
    if (value === undefined) continue;

    const current = Object.prototype.hasOwnProperty.call(result, key)
      ? result[key]
      : undefined;
    if (isPlain(value)) {
      const target = isPlain(current)
        ? current
        : Object.create(Object.getPrototypeOf(value));
      setOwn(result, key, mergePlain(target, value));
    } else {
      setOwn(result, key, cloneValue(value));
    }
  }
  return result;
}

export function mergeLayers(...layers) {
  const result = {};
  for (const layer of layers) {
    if (layer === null || layer === undefined) continue;
    for (const [key, value] of Object.entries(layer)) {
      if (value === undefined) continue;

      const current = Object.prototype.hasOwnProperty.call(result, key)
        ? result[key]
        : undefined;
      if (isPlain(value)) {
        const target = isPlain(current)
          ? current
          : Object.create(Object.getPrototypeOf(value));
        setOwn(result, key, mergePlain(target, value));
      } else {
        setOwn(result, key, cloneValue(value));
      }
    }
  }
  return result;
}
